const $=id=>document.getElementById(id),langs={en:'English',es:'西班牙语',pt:'葡萄牙语',de:'德语',fr:'法语',it:'意大利语',ja:'日语',ko:'韩语',zh:'简体中文',ar:'阿拉伯语',id:'印尼语',th:'泰语',vi:'越南语',hu:'匈牙利语',pl:'波兰语',cs:'捷克语',bg:'保加利亚语',ro:'罗马尼亚语',ru:'俄语',he:'希伯来语',hr:'克罗地亚语',lt:'立陶宛语'};
const controls=['size','auto','ratio','position','font','padding','family','bold','italic','fg','bg'];
const defaults={size:'720,1280',auto:true,ratio:46,position:50,zoom:1,offsetX:0,offsetY:0,font:38,padding:45,family:'Arial',bold:true,italic:true,fg:'#111111',bg:'#ffffff'};
const sample='😍We knotted almost every night for the past 8 years.\n\nYet I thought it was nothing more than a contract marriage.💔\n\nSo when he found his fated mate, I smiled, “Congrats. Now you can reject me and go mark your fated mate.”\n\n“Reject you?” His jaw clenched.\n🔥“While I’m still inside you?”';
let copies=Array.from({length:5},()=>({en:sample,enabled:true,settings:{...defaults},image:null})),ci=0,selected=new Set(['es','pt','de']),busy=false,revision=0;
const imageLoad=src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('图片无法读取'));im.src=src});
const notify=t=>$('status').textContent=t,outputLangs=()=>[$('includeEnglish').checked?'en':null,...selected].filter(Boolean);
async function readImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请上传 JPG、PNG 或 WEBP 图片');if(file.size>25*1024*1024)throw Error('单张图片不能超过 25MB');let src=await new Promise((r,j)=>{let fr=new FileReader();fr.onload=()=>r(fr.result);fr.onerror=j;fr.readAsDataURL(file)});return {name:file.name,src,img:await imageLoad(src)}}
async function uploadTo(file,index){try{let image=await readImage(file);copies[index].image=image;revision++;refresh();notify(`素材 ${index+1} 图片已替换`)}catch(e){notify(e.message)}}
function buildCards(){$('materialGrid').replaceChildren();copies.forEach((c,i)=>{let card=document.createElement('article');card.className='material-card';card.innerHTML=`<div class="section-head"><label><input type="checkbox" class="use"> 素材 ${i+1}</label><button class="detail">精调</button></div><canvas class="mini"></canvas><label class="button upload-one">点击或拖入图片替换<input type="file" accept="image/png,image/jpeg,image/webp" hidden></label><p class="muted">共用英语源文案 · 图片与版式独立</p><label><input type="checkbox" class="auto-mode"> 文案自适应图片高度</label><label>图片占比 <output class="card-ratio-value"></output><input type="range" class="card-ratio" min="15" max="75" aria-label="素材 ${i+1} 图片高度"></label><small class="card-state"></small>`;
card.querySelector('.use').checked=c.enabled;card.querySelector('.use').onchange=e=>{c.enabled=e.target.checked;revision++;refresh()};card.querySelector('.detail').onclick=()=>{ci=i;sync()};card.querySelector('input[type=file]').onchange=e=>{if(e.target.files[0])uploadTo(e.target.files[0],i);e.target.value=''};card.querySelector('.auto-mode').onchange=e=>{c.settings.auto=e.target.checked;revision++;if(ci===i)loadControls();refresh()};card.querySelector('.card-ratio').oninput=e=>{c.settings.ratio=Number(e.target.value);c.settings.auto=false;revision++;if(ci===i)loadControls();refresh()};bindFileDrop(card,files=>replaceFromFiles(files,i));$('materialGrid').append(card)});}
function loadControls(){controls.forEach(id=>{$(id)[$(id).type==='checkbox'?'checked':'value']=copies[ci].settings[id]});$('activeTitle').textContent=`素材 ${ci+1} · 顶部画面`;}
function sync(){loadControls();$('copy').value=copies[ci].en;$('copyTabs').replaceChildren();copies.forEach((c,i)=>{let b=document.createElement('button');b.textContent='素材 '+(i+1);b.className=i===ci?'selected':'';b.onclick=()=>{ci=i;sync()};$('copyTabs').append(b)});refresh()}
function refresh(){let codes=['en',...selected];for(let id of ['previewLang']){let sel=$(id),prev=sel.value;sel.replaceChildren();codes.forEach(code=>sel.add(new Option(langs[code],code)));if([...sel.options].some(o=>o.value===prev))sel.value=prev}let chosen=copies.filter(c=>c.enabled),missingLanguages=outputLangs().filter(l=>chosen.some(c=>!c[l]?.trim()));$('sourceStatus').textContent=`${copies[0].en.trim()?"已读取共用英语源文案":"请先填写英语源文案"} · 应用于 ${chosen.length} 个已选素材。每种语言只翻译一次，同步用于全部 5 张素材。`;$('total').textContent=chosen.length*outputLangs().length+' 个输出素材';$('summary').textContent=`${chosen.length} / 5 个素材已选 · ${outputLangs().length} 种导出语言`+(missingLanguages.length?` · 待生成：${missingLanguages.map(l=>langs[l]).join('、')}（无需重复输入原文）`:' · 所选语言已生成');$('imageCount').textContent=copies[ci].image?.name||'未上传图片';$('imageList').replaceChildren();render();document.querySelectorAll('.material-card').forEach((card,i)=>{let c=copies[i];card.classList.toggle('current',ci===i);card.querySelector('.auto-mode').checked=c.settings.auto;card.querySelector('.card-ratio').value=c.settings.ratio;let r=paint(card.querySelector('canvas'),c.image?.img,c,$('previewLang').value||'en');card.querySelector('.card-ratio-value').textContent=r.ratio+'%'+(c.settings.auto?' · 自动':'');card.querySelector('.card-state').textContent=!c.image?'请上传图片':r.fit?'✓ 排版适配 · '+r.size+'px':(!c[$('previewLang').value||'en']?.trim()?'该语言尚未生成译文':'文案过长，请调整版式')})}
Object.entries(langs).filter(([l])=>l!=='en').forEach(([l,name])=>{let label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.lang=l;input.checked=selected.has(l);input.onchange=()=>{input.checked?selected.add(l):selected.delete(l);revision++;refresh()};label.append(input,' '+name);$('languages').append(label)});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===b));['content','layout','translate'].forEach(x=>$(x).hidden=x!==b.dataset.tab)});
function setSharedSource(text){for(let c of copies){for(let lang of Object.keys(langs))if(lang!=='en')delete c[lang];c.en=text;}revision++;}
$('copy').oninput=()=>{setSharedSource($('copy').value);refresh();notify('英语原文已同步至 5 张素材；原译文已清除，请重新生成目标语言。')};
$('previewLang').onchange=refresh;$('includeEnglish').onchange=()=>{revision++;refresh()};controls.forEach(id=>$(id).oninput=()=>{copies[ci].settings[id]=$(id).type==='checkbox'?$(id).checked:$(id).value;if(id==='ratio'){copies[ci].settings.auto=false;$('auto').checked=false}revision++;refresh()});
async function replaceFromFiles(files,index){if(files.length!==1)return notify('单个素材请拖入 1 张图片；多张图片请拖到批量上传区');await uploadTo(files[0],index);}
async function uploadBatch(files){if(!files.length)return notify('未找到可读取的图片文件，请勿拖入文件夹');if(files.length>5)return notify('每次最多上传 5 张图片，未替换任何素材');try{let loaded=await Promise.all(files.map(readImage));loaded.forEach((im,i)=>copies[i].image=im);revision++;refresh();notify(`已依次替换素材 1–${loaded.length} 的图片`)}catch(e){notify('批量上传失败，未替换任何素材：'+e.message)}}
$('images').onchange=e=>{let files=[...e.target.files];if(files.length)replaceFromFiles(files,ci);e.target.value=''};
$('batchImages').onchange=e=>{let files=[...e.target.files];if(files.length)uploadBatch(files);e.target.value=''};
bindFileDrop($('singleDrop'),files=>replaceFromFiles(files,ci));
bindFileDrop($('batchDrop'),uploadBatch);
