function wrap(ctx,text,max){let lines=[];for(const paragraph of text.split('\n')){if(!paragraph.trim()){lines.push('');continue}let line='';const tokens=paragraph.match(/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Thai}]|[^\s\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Thai}]+\s*|\s+/gu)||[];for(let token of tokens){if(ctx.measureText(line+token.trimEnd()).width>max&&line){lines.push(line.trimEnd());line=''}if(ctx.measureText(token.trimEnd()).width>max){for(let char of Array.from(token)){if(ctx.measureText(line+char).width>max&&line){lines.push(line);line=''}line+=char}}else line+=token;}if(line)lines.push(line.trimEnd())}return lines;}
