overlay.addEventListener('pointerup',stopImageDrag);overlay.addEventListener('pointercancel',stopImageDrag);overlay.addEventListener('lostpointercapture',e=>{if(imageDrag&&imageDrag.id===e.pointerId){imageDrag=null;loadControls();refresh()}});
$('imageZoom').oninput=()=>{copies[ci].settings.zoom=Number($('imageZoom').value)/100;revision++;refresh()};
$('resetImage').onclick=()=>{Object.assign(copies[ci].settings,{zoom:1,offsetX:0,offsetY:0,position:50});revision++;loadControls();refresh()};
overlay.addEventListener('wheel',e=>{if(!copies[ci].image)return;e.preventDefault();let s=copies[ci].settings;s.zoom=Math.max(1,Math.min(4,(Number(s.zoom)||1)*Math.exp(-e.deltaY*.001)));revision++;refresh()},{passive:false});
